window.YSLYR=Object.assign(window.YSLYR||{}, {"y5-01": {"lines": [{"spk": "웨이", "t": "제임스 씨는 신문 기자라는 직업상 필요해서 한국어를 배우게 되셨다고 하셨지요?"}, {"spk": "제임스", "t": "네, 아시다시피 갑자기 한국 지사로 파견되는 바람에 한국어가 당장 필요했거든요."}, {"spk": "웨이", "t": "저도 그래요. 저도 우리 회사 일 때문에 한국어를 배우는 거예요."}, {"spk": "웨이", "t": "일하면서 배우려니 공부할 시간은 없고 갈수록 문법은 복잡해지고. 그래서 걱정이에요."}, {"spk": "제임스", "t": "그렇지요. 처음 가나다라를 배울 때만 해도 좋았지요? 그때는 이렇게 문법이 어려울 거라고는 생각조차 못했잖아요. 참, 리에 씨는 한국말을 배수는 특별한 이유가 없다고 하셨지요?"}, {"spk": "리에", "t": "네, 저는 한국 문회를 접하고 싶어서 한국에 왔어요."}, {"spk": "리에", "t": "사실 요즘 갈수록 문법이 복잡해지고는 있지만 한국어로 말하는 게 점점 재미있어져서, 저는 요즘 정말 즐거워요."}, {"spk": "웨이", "t": "정말 부럽네요. 리에 씨는 즐기면서 배우고 계시네요."}, {"spk": "제임스", "t": "한국 문화 글쎄요, 한국 노래를 좋아해서 자주 듣다보니 한국말을 배우고 싶어졌어요."}, {"t": "", "br": 1}, {"spk": "다나까", "t": "선생님, 안녕하십니까? 어제 전화 드린 다나까마사오입니다."}, {"spk": "김영식", "t": "오랜만이네, 어서 오게, 그래 무슨 일로 날 보자 했나?"}, {"spk": "다나까", "t": "저… 다름이 아니라 일본어와 한국어 모두 능통한 경영학 전공자를 인턴사원으로 모집한다는 채용 공고가 나서 제가 지원을 할까 하는데요. 선생님, 번거롭게 해 드려 죄송한데 추천서를 좀 부탁 드리려고 왔습니다."}, {"spk": "김영식", "t": "그래, 내가 써주지, 그런데 말이야, 자네를 볼 때마다 느끼는 건데 어떻게 그렇게 한국말을 잘 하나? 자네, 이름을 얘기 안 하면 밖에서들 한국 사람인줄 알지?"}, {"spk": "다나까", "t": "아닙니다 아직 부족한 점이 많습니다."}, {"spk": "김영식", "t": "자년! 참 겸손하기도 하군 그래. 추천서 써 가지고 과 사무실에 맡겨 놓을 테니 내일 모레쯤 찾아가게."}, {"spk": "다나까", "t": "선생님. 고맙습니다. 다시 찾아뵙겠습니다. 안녕히 계십시오."}, {"spk": "김영식", "t": "언제 식사나 한번 하세. 좋은 소식 전해 주게."}, {"t": "", "br": 1}, {"spk": "가", "t": "오랜만이네, 자네 요즘 어떻게 지내나?"}, {"spk": "나", "t": "얼마 전에 우리 딸이 첫 아이를 낳아서 요즘 손자 보느라고 정신이 없다네."}, {"spk": "가", "t": "자네가 벌써 할아버지가 됐군 그래, 누굴 닮았나?"}, {"spk": "나", "t": "제 아비랑 붕어빵이라네. 언제 한번 우리 손자 보러 집에 오게."}, {"spk": "가", "t": "그러세. 작품에 손대지 마시오. 신발을 벗고 들어가시오."}, {"spk": "나", "t": "너 이번 주말에 별일 없니?"}, {"spk": "가", "t": "별일 없어. 그런데 왜 그래?"}, {"spk": "나", "t": "우리 집에 와서 저녁이나 같이 하자."}, {"spk": "가", "t": "아니, 그냥…-… 그날 우리 집에 꼭 와."}, {"spk": "나", "t": "자네 이번 주말에 별일 없나?"}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "정규 과정"}, {"t": "세부 내용을 정확하게"}, {"t": "들어야 함"}, {"t": "알다시피"}, {"t": "지사"}, {"t": "파견"}, {"t": "당장"}]}, "y5-02": {"lines": [{"spk": "영수", "t": "졸업 후에 어떤 일을 해야 할지 고민이에요."}, {"spk": "제임스", "t": "무엇보다 자신에게 맞는 일, 자신이 하고 싶은 일을 짖아야 하지 않을까요? 통계청 조사에 따르면 청년 취업자의 반 이상이 17개월 안에 첫 직장을 그만둔다는데요."}, {"spk": "영수", "t": "정말 그런 것 같아요. 4년 째 직장 생활을 하고 있는 선배가 있는데, 요즘도 일 이 적성에 안 맞는다며 많이 힘들어하던데요. 사실 직장을 옮기는 것도 쉽지 않고, 주위에서도 웬만하면 그냥 다니라고들 하니까요."}, {"spk": "제임스", "t": "수십 대 일의 경쟁을 뚫고 어렵게 입사하고도 얼마 지나지 않아 그만두는 직 장인이 많다는 건, 사람들이 직업에 대한 구체적인 정보도 잘 알아보지 않거니와 흥미와 적성을 신중히 고려하지 않기 때문은 아닐까요?"}, {"spk": "영수", "t": "글쎄 말이에요. 어쩌면 보수와 장래성이 아니라 자신의 성격과 가치관이 제일 중 요한 건지도 모르겠네요."}, {"spk": "제임스", "t": "왜, 영수 씨도 아시죠? 안철수 같은 분도 어려운 과정을 거쳐 의사가 되었음에도 불구하고 진정 하고 싶은 일을 하겠다는 의지로 컴퓨터 소프트웨어 업계에 뛰어 들어 성공했다는 거요."}, {"spk": "영수", "t": "아, 저도 그 기사를 읽었어요. 소신을 가지고 자신이 하고 싶은 일을 하며 보람을 느낄 수 있는 사람이 행복한 사람이라고 하시더군요."}, {"spk": "영수", "t": "직업에 대한 구체적인 정보도 잘 알아보지 않을뿐더러 자신의 홍미와 적성을 신중"}, {"t": "", "br": 1}, {"spk": "김 과", "t": "지난번에 지시하신 소비자 동향 분석 결과입니다."}, {"spk": "김 과", "t": "직접 현장에 나가 현재 판매 중인 상품에 대한 시장 조사를 하고 신제품 개발에 대한 소비자 요구를 조사했습니다."}, {"spk": "조 부", "t": "수고 많았네. 그래, 현장 조사는 어떻게 진행했나?"}, {"spk": "김 과", "t": "대형 할인점과 백화점, 전문 매장으로 나눠서 소비자들의 반핑을 조사했습니다."}, {"spk": "김 과", "t": "설문에 응해 준 소비자들에게는 회계과에서 받은 비용으로 자그마한 사은품-을 증 정했고요."}, {"spk": "조 부", "t": "역시 김 과장이야. 매사에 빈틈없이 꼼꼼하게 일 처리를 하고."}, {"spk": "김 과", "t": "별 말씀을요! 당연히 제가 해야 할 일인데요."}, {"spk": "조 부", "t": "아, 그리고 우리 부서 단합 대회 한 번 해야지. 이럴 때 한잔해야 또 일할 맛 나지."}, {"spk": "조 부", "t": "김 과장이 다른 직원들이랑 상의해서 날 잡아 봐요. 찌는 내가 책임질 테니까."}, {"spk": "김 과", "t": "알겠습니다. 그렇지 않아도 모두들 요 며칠 야근에다가 주말 근무까지 하느라 힘 들었거든요."}, {"spk": "김 과", "t": "박 대리 : 이번 금요일 어때요? 다음날이 연휴니까 늦게까지 마셔도 부담없고• 이 대리 : 그러지 말고 이번 토요일에 등산 같은 거 가는 게 어때요?"}, {"t": "", "br": 1}, {"spk": "영수", "t": "젊은 박사 부부가 남들이 부러워하는 모든 걸 다 버리고 시골로 내려갔다는 뉴스 들었지? 정말 대단하지 않아?"}, {"spk": "민호", "t": "난 공감이 되는데. 어차피 대도시의 직장생활은"}, {"spk": "영수", "t": "그렇지만 힘들게 얻은 그렇게 다 버리는 건 쉽지 않은 일이야."}, {"spk": "민호", "t": "그래도 이 사람들처럼 자신이 옳다고 판단했을 때 여야 좀 더 멋진 삶을 살 수 있지. 나도 할 수만 있다면 그렇게 하고 싶어."}, {"spk": "영수", "t": "까지 있는데도 어떻게 처벌을 안 받았지?"}, {"spk": "영수", "t": "어야/아야/여야 국민들로부터 신뢰와 지 지를 얻을 수 있을 텐데 말이여"}, {"spk": "민호", "t": "거니와 탈세 같은 불법적인 일은 우리 사회에 있어서는 절대로 안될 일이지."}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "동향 분석"}, {"t": "소신 보람"}, {"t": "가치관"}]}, "y5-03": {"lines": [{"spk": "제임스", "t": "아, 민철 씨. 지금 출근하세요?"}, {"spk": "인철", "t": "네. 제임스 씨, 아직 이른 시간인데 오늘은 일찍 출근하시네요. 그런데 들고 계 신 샌드위치는 아침이에요?"}, {"spk": "제임스", "t": "네. 일찍 온 김에 지하철역 근처의 샌드위치 가게에서 한 번 사 봤어요. 민철 씨는 식사하셨어요?"}, {"spk": "인철", "t": "아직요. 교통 체증을 피하느라고 일찍 나오다보니 집에서는 아침을 먹기가 힘들어요."}, {"spk": "제임스", "t": "저도 그렇지만 요즘 사람들이 바쁘긴 바쁜가 봐요. 빵 한 조각으로 때울 시간이 없어서 아침을 거르기가 일쑤인 걸 보면요. 식사를 제대로 해야 건강도 잃지 않을 텐데 말이에요."}, {"spk": "인철", "t": "그래서 저는 어떻게든 아침을 챙겨 먹으려고 하는 편이에요. 아침식사를 배달하는 업체가 있길래 얼마 전부터 거기에 주문해서 먹고 있어요. 사무실까지 배달도 해 주니까 여러 모로 편리하고 무엇보다 시간이 절약되어서 좋아요."}, {"spk": "제임스", "t": "어, 그거 좋은 방법이군요. 통근 시간도 단축되고 교통 체증에도 시달리지 않고 제대로 된 아침식사도 하고, 일석삼조군요."}, {"t": "", "br": 1}, {"spk": "가", "t": "저 식당 유명하잖아. 손님이 끊이질 않아."}, {"spk": "나", "t": "그래? 음식이 맛있긴 맛있나 보다."}, {"spk": "가", "t": "야, 저 중학생들 카 좀 봐. 정말 크다."}, {"spk": "나", "t": "요즘 아이들 평균 기가 우리 세대에 비해 10센티 이상 크대."}, {"spk": "가", "t": "요즘 아이들의 기가"}, {"spk": "나", "t": "핸드폰이 없으면 너도 불안하니?"}, {"spk": "가", "t": "응, 나도 요전에 핸드폰을 집에 두고 나왔다가 정말 하루 종일 안절부절 못했지 뭐야."}, {"spk": "나", "t": "우리가 요즘 핸드폰에 너무"}, {"spk": "가", "t": "너도 이 옷 샀구나. 요새 이 옷 눈에 많이 띄더라."}, {"spk": "나", "t": "난 그냥 예뻐서 샀는데?"}, {"spk": "가", "t": "패션에 관심 없던 너까지 사 입은 걸 보니 이 옷이"}, {"spk": "나", "t": "저 사람들은 만날 싸우면서도 왜 안 헤어져?"}, {"spk": "가", "t": "정 때문에 헤어지기가 그리 쉽겠어?"}, {"spk": "나", "t": "정이"}, {"t": "", "br": 1}, {"spk": "김 부", "t": "아니, 웨이 씨. 주말에 무슨 일이 있었습니까? 월요일 오전부터 책상 앞에서 꾸벅꾸벅 졸고 있으니… 주 5일 근무제라 주말에 편히 쉴 수 있잖아요."}, {"spk": "웨이", "t": "죄송합니다. 근데 전 편히 쉬기는커녕 주말에도 술 약속이 생겨서 월요일 아침이 더 힘드네요."}, {"spk": "김 부", "t": "하긴 신문을 보니까 늘어난 여가 시간에 월 해야 좋을지 모르는 사람들이 많다더군요. 그렇지만 그 시간을 잘 활용하는 사람도 있지요. 거 왜 영업부의 박 대리는 주말마다 사진을 찍으러 가고, 총무부의 윤지현 씨는 재즈 댄스를 배우나 보던데."}, {"spk": "웨이", "t": "저라고 왜 그러고 싶지 않겠어요. 근데 친구들이 주말마다 한잔하자는 바람에 계속 술을 마시게 되네요."}, {"spk": "김 부", "t": "웨이 씨도 뭔가 여가 시간을 알차게 보낼 방법을 찾아 보세요. 나는 주말마다 가족들과 등산을 했더니 기분전환도 될뿐더러 아들과 함께 보낼 수 있는 시간도 생기고 해서 좋던데요. 사실 바빠서 얼굴 보기도 힘들었거든요."}, {"spk": "웨이", "t": "그래야지요. 안 그래도 이번 주말부터는 보고 싶던 연극이나 뮤지컬 관람을 할까 해요. 귀한 여가 시간인데 좀 더 보람 있게 생산적으로 보내야겠지요. 그러면 한 주 동안 일에 지친 몸이 재충전도 될 테고."}, {"spk": "웨이", "t": "하루 종일 TV만 보고 참만 자니까…"}]}, "y5-04": {"lines": [{"spk": "웨이", "t": "제임스 씨, 인터넷에서 쓰는 이름이 특이하면서도 친근하데요."}, {"spk": "제임스", "t": "아, 지난 번 제 홈페이지에 들렀다가 보셨군요."}, {"spk": "제임스", "t": "처음에 한국 친구들이 재미로 부르던 별명이었는데 어느새인지 친숙해지더라고요."}, {"spk": "웨이", "t": "네, 아주 반가웠었어요. 저같이 007 영회를 즐겨보는 사람에게는."}, {"spk": "웨이", "t": "근데 아주 잠시 '진짜 한국인 본드는 어느 나라 사람일까 생각했어요."}, {"spk": "제임스", "t": "아니, 그런 생각을 하시다니요? 그냥 가볍게 한국 친구들과 인터넷으로 만날 때 쓰는 이름인걸요."}, {"spk": "웨이", "t": "그러셨군의 저도 회사 메일 아이디, 개인 메일 아이디, 친구들 사이트용 아이디 등 아이디만 해도 서너 개가 있지만, 대충 숫자랑 문자를 조합해서 만들었어요."}, {"spk": "제임스", "t": "맞아요, 저도 보통은 그런데, 제 홈피에서만은 좀 특별한 이름을 쓰고 싶었답니다."}, {"spk": "제임스", "t": "제임스 : 네, 한국 사람들이고 007 영화도 즐기는 친구들이라서 그런지 아주 재미있어하"}, {"t": "", "br": 1}, {"spk": "가", "t": "네, 나무가 많고 쉴 곳이 많아서 아주 쾌적하다"}, {"spk": "나", "t": "어제 방문한불로그는 어떠셨어요?"}, {"spk": "가", "t": "볼만한사진이 엄청 많데요."}, {"spk": "나", "t": "이번에 대학에 수석 합격한소녀 가장이 자신의 홈페이지에 남긴 글 보셨어요?"}, {"spk": "가", "t": "네, 정말"}, {"spk": "나", "t": "첫사랑이라서 더욱 오래 잊지 못했구나"}, {"spk": "가", "t": "응, 그 해맑게 웃던 모습을 정말"}, {"spk": "나", "t": "그 친구가 올린 동영상이 재미있던가요?"}, {"spk": "가", "t": "이번에 새로 생긴 공원이 어때?"}, {"t": "", "br": 1}, {"spk": "제임스", "t": "요즘은 과학의 발달로 예전에는 상상조차 못했던 일들이 가능해지고 있어요."}, {"spk": "웨이", "t": "그렇지요? 앞으로는 생명 과학의 발달로 원하는 유전 인자만을 선택해 맞춤형 아 이를 낳고 인간의 복제도 기능해지는 세상이 올 거라고들 해요."}, {"spk": "제임스", "t": "양이나 소는 이미 오래 전에 복제에 성공한 사례가 있지요? 복제 기술이 좀 더 발 전하게 된다면 인류는 어떻게 될까요?"}, {"spk": "웨이", "t": "복제 기술을 이용한 장기 이식이 가능해져 불치병도 쉽게 고치고 수명도 길어지겠 지요? 살기 좋은 세상이 될 거예요."}, {"spk": "제임스", "t": "그렇지만 그런 일은 자연의 이치에 어긋나는 일이 아닐까요? 과학과 기술의 발달 이 인간에게 가져다주는 혜택은 누리되 그 부작용도 생각해야 한다고 봅니다. 옳 고 그름을 따질 수 있는 정확한 기준을 마련하지 않는 한 크나큰 문제를 일으킬 수 도 있을 테니까요."}, {"spk": "웨이", "t": "그렇게 부정적으로만 생각할 필요는 없다고 봅니다. 저는 과학과 기술의 발달이 인간의 생활에 미치는 긍정적인 영향이 훨씬 더 크다고 보는데요."}, {"spk": "웨이", "t": "웨 이:"}, {"t": "", "br": 1}, {"t": "노사 문제를 해결할 수 있는 방법이 없습니다."}, {"t": "현대 사회의 경쟁에서 살아남을수 없습니다."}, {"t": "선진국으로 발돋움하기 어렵습니다."}, {"t": "[보기] 자신을 통제할 수 있는 의지력을 갖고 있지 않는 한 컴퓨터와 인터넷의 발달은 인간 에게 해로울 수도 있다."}, {"t": "다음을 보고 '-되' , '-는 한을 사용해 보기와 같이 이야기해 봅시다."}, {"t": "", "br": 1}, {"t": "실패를 두려워하면 발전을 못한다."}, {"t": "건강을 지키지 못하면 아무 일도 할 수 없다."}, {"t": "제품의 질이 앞서지 않으면 경쟁력이 없다."}, {"t": "인간이 자신의 행동을 통제할 윤리관을 갖추지 않으면 과학은 재앙을 가져올 수 있다."}, {"t": "무모한 도전은 피하되 도전 정신을 잃지는 마십시오. 실패를 두려워하는 한 큰 발"}, {"t": "", "br": 1}, {"spk": "미선", "t": "옆집에 새로 이사 온 가족 봤어요? 아이도 하나 있던데요."}, {"spk": "영수", "t": "네, 그런데"}, {"spk": "미선", "t": "요즘 많은 아이들이 그렇지요. 자식을 너무 귀하게 기워서 그런가 봐요."}, {"spk": "영수", "t": "그 아이만 그런 게 아니라"}, {"spk": "미선", "t": "저런, 윗물이 맑아야 아랫물이 맑다는 옛말이 들리지 않네요."}, {"t": "", "br": 1}, {"spk": "가", "t": "인터넷이 대중화되면서 그에 따른 부작용이나 범죄가 증가하고 있지요?"}, {"spk": "나", "t": "네, 얼마 전에 우리나라 청소년들을 대상으로 실시한 설문조시를 보니"}, {"spk": "가", "t": "맞아요. 얼마 전에 한 젊은이가 PC방에서 수십 시간 동안 쉬지 않고 온라인 게임을"}, {"spk": "나", "t": "하다가 사망한 사고도 있었잖아요?"}, {"spk": "가", "t": "안 되는데요."}, {"spk": "나", "t": "조사 결괴를 보면 인터넷에서"}, {"spk": "가", "t": "그것도 큰 문제지요. 어렵게 만든 저작물이 권리를 보호받지 못하고 있으니 말입니다."}, {"spk": "나", "t": "관련법을 제정하여"}]}, "y5-05": {"lines": [{"spk": "마리아", "t": "왜 그렇게 잔뜩 화가 났어?"}, {"spk": "미선", "t": "방금 세탁소에 갔다 왔는데, 이것 봐. 스웨터가 한쪽은 늘어나고 한쪽은 줄어들었잖 아. 입을래야 입을 수가 없게 생겼는데 주인은 괜찮다는 거야."}, {"spk": "마리아", "t": "어디 봐. 그러게, 이쪽 오른 팔이 더 기네."}, {"spk": "미선", "t": "그래! 그냥 눈으로 봐도 이렇게 확연히 차이가 나는데 주인은 별로 표가 안 난다는 거야."}, {"spk": "마리아", "t": "보상해 달라고 하지 그랬어?"}, {"spk": "미선", "t": "보상해 달라고 그랬지. 그랬더니 보상은 고사하고 사과 한 마디 없더라고. 나 원 참."}, {"spk": "마리아", "t": "그럼, 소비자 보호원에 고발해. 요즘은 소비자 보호법 덕분에 이렇게 피해를 입은 경우는 손해 배상을 받을 수 있잖니."}, {"spk": "미선", "t": "그렇지 않아도 지금 고발을 할까 말까 생각 중이야."}, {"t": "", "br": 1}, {"spk": "미선", "t": "그게 무슨 말이에요? 설마 보너스로 주식을 샀던 건 아니겠죠?"}, {"spk": "미선", "t": "사실 미선 씨에게 말은 못했는데요. 김 대리가 크게 이익을 봤다고 하길래 나도 한 번 해 본 건데, 이렇게 될 줄 누가 알았나요?"}, {"spk": "미선", "t": "그러게 남들 한다고 무작정 따라 해요? 한탕 해 보겠다는 마음으로 하는 게 투기지 무슨 투자예요?"}, {"spk": "인철", "t": "김 대리가 자꾸만 조금 더 오르면 팔자고 그러지 뭐예요? 주가가 무릎일 때 사고 어 깨에서 필이야 한다는데. 그러다가 주가가 갑자기 떨어지는 바람에… 에이 참, 욕심을 덜 부리면 될 것을."}, {"spk": "미선", "t": "주식 투자는 위험 부담이 크지 않아요? 몇 년이 걸리더라도 한 푼 두 푼 내 힘으 로 모으는 게 마음 편할 것 같은데요."}, {"spk": "인철", "t": "미선 씨는 주식을 너무 부정적으로 생각하는 것 같네요. 요즘처럼 은행 금리가 낮을 때는 주식 투자를 해야 하는 거라고요. 주식에 투자하는 것도 국가 경제나 기 업 경제 활동에 도움이 된다고요."}, {"spk": "미선", "t": "그걸 누가 모르나요? 문제는 장기적인 안목이나 계획성을 가지고 투자하는 게 아 니라 주식 투자가 무슨 복권이라도 되는 양 일단 사고 보지는 식이니 그렇죠."}, {"spk": "미선", "t": "네, 옆자리에 앉은 김 대리가 해 보라고 해서 했대요. 좀 더 오르면 팔려다가 주가"}, {"t": "", "br": 1}, {"spk": "민철", "t": "을까/근까 말까 생각 중이야."}, {"spk": "민철", "t": "그렇지만 그 카메라가 자꾸 눈앞에 아른거리는 걸 어떻게 해!"}, {"spk": "영호", "t": "을까/근까 말까 생각 중이에요."}, {"spk": "영호", "t": "더라도 그 이자도 만만치 않을테고… 그렇다고 그냥 이대로 월급쟁이 노릇만 하고 살 순 없을 것 같아요."}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "소비자"}, {"t": "소비자 보호원"}, {"t": "고객 상담실"}, {"t": "하자가 있다"}, {"t": "청구하다"}, {"t": "신고하다"}, {"t": "고발하다"}]}, "y5-06": {"lines": [{"spk": "제임스", "t": "네. 오랜만에 여러 나라의 다양한 영회를 접하고 왔어요. 참여국이나 출품된 작품 들의 수준으로 봤을 때 이제 부산영화제는 세계 영화제로 자리 잡은 듯싶어요."}, {"spk": "인철", "t": "최근의 영회를 두루 관람하고 오셨다니 부럽네요. 뭐 눈길을 끌 만큼 특징적인 것 이라도 있었나요?"}, {"spk": "제임스", "t": "한마디로 최근의 경향은 전통의 현대화라고도 할 수 있을 것 같아요. 흥미로운 소재는 시대와 장르를 넘나들며 색다르게 다루어지더라고요."}, {"spk": "인철", "t": "맞아요. 소설 〈춘향전〉도 영회는 물론이고, 뮤지컬과 드라마로도 만들어졌지요."}, {"spk": "인철", "t": "역시 과거나 현재나 대중들의 사랑을 받는 소재는 변함없는 생명력을 지니고 있는 것 같아요."}, {"spk": "제임스", "t": "네. 그래서 다음에는 현대 대중문화에서 발견할 수 있는 과거와 현재, 그리고 만화 나 영화 등의 장르 간의 소통을 기획 기사로 써 볼까 합니다. 외국인들에게도 인기 가 있는 〈난타〉도 시물놀이의 장단을 연극 무대에 올린 것 아니겠어요?"}, {"spk": "제임스", "t": "제임스:"}, {"t": "", "br": 1}, {"spk": "영수", "t": "한국 전통 무용을 관람한 소감이 어때요? 리에 씨 나라의 춤과는 좀 다르지요?"}, {"spk": "리에", "t": "그렇네요. 우리나라랑 가까워서 비슷할 거라고 생각했는데, 많이 다르네요."}, {"spk": "영수", "t": "저는 조금 전에 본 태평무를 가장 좋아하는데, 리에 씨는 어땠어요?"}, {"spk": "리에", "t": "좀 느린 듯하면서도 동작이 크고 우아해서 한복의 곡선미와 잘 어우러진 느낌이었 어요. 시간과 공간에 걸친 여백의 미랄까? 하지만 저는 태평무보다 시물놀이가 더 미음에 들던데요."}, {"spk": "영수", "t": "아, 시물놀이요? 관객들도 같이 어깨를 들썩거리면서 즐길 수 있어서 좋았지요."}, {"spk": "리에", "t": "네. 정말 인상적이었어요. 장구나 꽹과리를 빠르게 치는 신명 나는 몸짓이 한국 전 통 예술의 역동적인 면을 보여주는 것 같더군요. 근데, 이번 시물놀이 연주자들은 개량 한혁을 입고 나왔던데요."}, {"spk": "영수", "t": "요즘은 전통 예술도 옛것만 고집하지 않고 현대화하거나 대중화하려는 노력을 많이 해요. 사실 대중에게 다가서지 못한다면 전통-을 고수한들 무슨 의미가 있겠어요?"}, {"spk": "리에", "t": "저는 옛날 그대로의 모습이 더 좋아요. 대중화나 현대화가 중요하니 어쩌니 해도, 있던 그대로의 전통을 보존하는 것이 더 중요하다는 생각이 들기도 하고요."}, {"spk": "리에", "t": "리에 : 하지만 그렇게 되면 우리는 조상이 물려주신 그대로의 모습을 차차 잃어 가겠지"}, {"t": "", "br": 1}, {"spk": "최 선", "t": "김 선생님 댁은 직접 메주를 띄우시데요!"}, {"spk": "박 선", "t": "최 선생님도 보셨군요. 김 선생님 택에서는 장을 모두 직접 담가서 드신대요."}, {"spk": "최 선", "t": "요즘도 장을 직접 담가 먹는 집이 있나요?"}, {"spk": "박 선", "t": "그 택은 3대가 같이 살아서 아무래도"}, {"spk": "최 선", "t": "그래도 장 담그는 건 보통 번거로운 일이 아닐 텐데…건강 때문인가요?"}, {"spk": "박 선", "t": "는다고도/L다고도/ 그렇기도 하지만 다고도/이라고도/라고도 할 수 있겠지요. 아무리"}, {"spk": "최 선", "t": "니 어쩌니 해도 직접 담가 먹는 것만 하겠어요?"}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "기획 각색 제작 방송"}, {"t": "수수하다 투박하다"}, {"t": "연출 공연 감독"}, {"t": "동적이다 정적이다"}, {"t": "시청자 관객 청중"}, {"t": "해학적이다 우아하다"}, {"t": "전통 예술"}, {"t": "현대 대중예술"}, {"t": "판소리"}, {"t": "탈춤"}, {"t": "도자기"}, {"t": "산수화"}, {"t": "연극"}, {"t": "영화"}, {"t": "콘서트"}, {"t": "고여"}]}, "y5-07": {"lines": [{"spk": "웨이", "t": "정회 씨는 외동딸이고 집도 서울인데 왜 하숙집에서 살아요?"}, {"spk": "정회", "t": "직장이 멀어서요. 집에서 다니자니 출되근시간이 힘들고 가족 모두가 이사를 하 자니 그것도 쉽지 않고 해서 저만 나와서 혼자 살아요. 왜요? 이상해요?"}, {"spk": "웨이", "t": "아니요, 이상하다기보다 한국은 성인이 되어도 결혼하기 전까지는 부모님이랑 같이 사는 게 일반적이라고 들어서요."}, {"spk": "정회", "t": "하지만 요즘은 많이 달라졌어요. 결혼 전에 독립하는 사람도 많아요. 가족의 형 태도 많이 달라진 것 같고요. 1인 가구도 가족의 한 형태로 인정해야 된다는 말 이 나올 정도니까요."}, {"spk": "웨이", "t": "그러고 보니 혼자 사는 젊은이들도 많긴 하네요. 한국도 명절 때는 보통 고향에 서 가족끼리 모인다고 하던데 요즘에는 그렇지 않은 건가요? 요즘 같은 저출산 시대에 자녀가 독립을 하면 가족끼리 얼굴 보기도 힘들 것 같아요."}, {"spk": "정회", "t": "그럴 리가 있겠어요? 역귀성이나 콘도 차례처럼 명절을 보내는 새로운 모습도 가족이 모이기 위해서 생각해낸 거잖아요. 혼자 사는 젊은이들이 많아지고 가족 주의적 가치관이 약해졌다고 해도 가족이 중요하다는 건 부정할 수 없지요."}, {"spk": "정회", "t": "정회: 그렇다고 해도 가족은 가족이지요."}, {"t": "", "br": 1}, {"spk": "제임스", "t": "검은색 정장을 입었네요. 어디 다녀오는 길이에요?"}, {"spk": "영수", "t": "네. 친구 아버님이 돌아가셨다는 소식을 듣고 문상을 다녀왔지요."}, {"spk": "영수", "t": "마음 같아선 밤을 새우고 장지까지 따라가고 싶었지만 워낙 요즘 연구소 일정이 빡빡해서요."}, {"spk": "제임스", "t": "친구 부모님이 돌아가시면 장지까지 따라가는 것이 보통인가요?"}, {"spk": "영수", "t": "아니, 뭐 꼭 그럴 것까지는 없겠지만 생전에 저에게도 퍽 잘해 주시던 분이셔서 요. 근데 조문객이 정말 많더라고요."}, {"spk": "제임스", "t": "조문객이 많으면 가족들이 초상을 치르느라 고생이 많을 것 같아요."}, {"spk": "영수", "t": "요즘엔 모든 장례 절치를 장례식장에서 다 맡아 해주어서 그나마 수월해 보였어요."}, {"spk": "제임스", "t": "전통적인 장례식과는 분위기가 다소 달랐겠군요. 그건 그렇고 장례식장에 갔을 때 가족들에게 어떻게 조의를 표해야 하는지 그것이 좀 궁금했는데 어떻게 하면 되나요?"}, {"spk": "영수", "t": "빈소에 들어가서 절하거나 묵념을 한 후에 옆에 서 있는 유족들에게 '고인의 명 복을 법니다.' 라고 말하는데요, 아무 말씀 안하시고 그냥 인사만 하셔도 됩니다."}, {"t": "", "br": 1}, {"spk": "수경", "t": "음식을 남겼네요. 맛이 이상해요?"}, {"spk": "수경", "t": "구내식당이 다 그렇지요 뭐."}, {"spk": "수경", "t": "같아서는"}, {"spk": "진수", "t": ". 음식 좀 제대로 만들 수 없나?"}, {"spk": "수경", "t": "을/근 것까지는 없겠지만"}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "빈소"}, {"t": "저출산"}, {"t": "부정하다"}, {"t": "역귀성"}, {"t": "문상"}, {"t": "장지"}, {"t": "생전"}, {"t": "명복"}, {"t": "초상을 치르다"}, {"t": "묵념"}, {"t": "고인"}, {"t": "절차"}, {"t": "조의를 표하다"}, {"t": "핵가족"}, {"t": "노인 가족"}, {"t": "비동거 가족"}, {"t": "편부모 가족"}, {"t": "대안가족"}, {"t": "고령화 사회"}, {"t": "이혼율 증가"}, {"t": "돌잔치를 하다"}, {"t": "제사를 지내다"}, {"t": "장래를 축복하다"}]}, "y5-08": {"lines": [{"t": "그건 한국 부모님들의 교육열이 높아서 그런 것 같아요. 가능하면 자식이 교육을 많이 받아서 사회적으로 성공하길 바라는 게 대다수 부모님들의 마음이지요."}, {"t": "저도 고등학교 때 학교 다니라 학원 다니라 날마다 시간에 쫓기면서 밤 늦게까지 책하고 씨름했었어요."}, {"t": "그렇게 열심히 공부해서 그런지 한국 학생들 보면 상식도 풍부하고 재주도 많은 것 같은데…. 그렇지만 공부에 쫓겨서 그런지 마음에 여유가 없어 보여요."}, {"t": "부모님들의 교육열이 높고 대입 경쟁이 치열하다 보니 그로 인해 부작용도 생기 고 있지만 높은 교육열 덕분에 한국이 이만큼 발전했다고도 하거든요. 한국은 천 연자원이 부족한 나라인데 교육 덕분에 인적자원이 풍부하다고들 하니까요."}, {"t": "", "br": 1}, {"t": "뭐 배우려고요? 저도 주말에는 쉬니까 월 좀 배울까 하고 있었는데… 저는 독서 논술 강죄를 들을까 해요. 공부해 두면 여러모로 쓸모가 많을 것 같아 요. 나중에 아이가 생기면 아이 가르치는 데도 도움이 될 것 같고요."}, {"t": "우리 하숙집 아주머니는 구청 복지관에서 한복하고 조각보를 배우신다고 하더라 고요. 벌써 중급 과정은 끝내고 고급 과정이래요. 지도자 과정까지 마칠 계획이 신가 봐요. 연세도 많으신데 열의가 대단하세요."}, {"t": "멋있는 분이네요. 요즘은 나이가 들어서도 끊임없이 배우고 자신을 계발하려는 사람이 많아진 것 같아요."}, {"t": "맞아요, 그렇게 하지 않고서는 삶의 질이 향상되기 어렵죠. 다양한 학습 기회를 제공해 주는 평생 교육이 이제는 필수적인 것이 된 것 같아요."}, {"t": "그래요. 평균 수명이 길어진 만큼 의미 있는 노후 생활을 위해서라도 뭔가 준비"}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "인적 자원"}]}, "y5-09": {"lines": [{"t": "네, 꼭 한번 가보리라 꿈꾸던 곳이었거든요. 역시 말로 형용할 수 없으리만치 멋 지더군요. 음, 구름 위에 우뚝 솟은 모습이 아직도 눈에 선해요."}, {"t": "등산을 자주 하시는 리에 씨가 그렇게 반할 정도라니 정말 대단한가 보군요."}, {"t": "산을 오르는 일은 언제나 산의 정기와 맑은 향을 느낄 수 있어 좋지요?"}, {"t": "리에 씨, 이번에야말로 이런 산의 정기와 향을 만끽하셨겠네요?"}, {"t": "글쎄요, 그렇게 즐기기에는 그 자연의 위용과 풍모가 너무 장엄해서요. 뭐랄까 태초 그대로인 자연의 험준한 산세에 눌려 압도당하는 기분이랄까? 인간이란 게 얼마나 보잘 것 없는 존재이던지요!"}, {"t": "와, 거대한 자연의 경이로움에 압도되셨군요. 저도 지난 번 아마존에서, 유유히 흐르는 물줄기를 보며 자연이란 결코 인간이 넘볼 상대가 아님을 느꼈거든요."}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "넘보다 만끽하다"}, {"t": "보잘 것 없다"}]}, "y5-10": {"lines": [{"spk": "정회", "t": "민철 씨, 금요일 저녁인데 데이트 안 하세요?"}, {"spk": "민철", "t": "아, 네. 여자 친구가 오늘 공부방에 봉사하러 가서요."}, {"spk": "정회", "t": "공부방요? 아, 생활이 어려운 집 아이들을 무료로 가르쳐주는 거 말이죠."}, {"spk": "정회", "t": "저도 대학생 때 해 볼까 했었는데 자신이 없더라고요."}, {"spk": "정회", "t": "해 보지 그랬어요? 사실, 저도 여자친구랑 같이 대학생 때 했었어요. 그 때는 공 부방에 가서 살다시피 했는데 직장 생활하다 보니 틈이 안 나네요."}, {"spk": "정회", "t": "요즘은 한 달에 만 원씩 결식 아동을 후원하는 재단에 기부를 하고 있어요."}, {"spk": "정회", "t": "적은 돈이지만 십시일반이라고들 하니까요."}, {"spk": "정회", "t": "어머, 그래요? 전 왠지 기부는 좀 많은 돈을 해야 한다는 생각이 들어서 생각도 못 했는데…"}, {"spk": "민철", "t": "그렇게 생각하기 쉬운데, 홍수 때 전화로 일이천 원씩 수재 의연금을 내기도 하 잖아요. 돈 액수가 문제가 아니라 이웃과 더불어 살아간다는 마음이 중요한 게 아닐까요?"}, {"spk": "정회", "t": "하긴 아무리 가진 것이 없다 해도 나눌 것은 있다고들 하지요. 저도 이제부터 적 은 돈이라도 기부할까 봐요."}, {"spk": "정회", "t": "정회 : 아름다운 재단요? 인터넷에서 찾을 수 있지요?"}, {"t": "", "br": 1}, {"spk": "가", "t": "장기 이식을 못해서 죽어기는 이들이 많다는 얘기를 듣고 장기 기증을 하기로 했어요. (헌혈)"}, {"spk": "나", "t": "그래요? 그럼 저는 헌혈이라도 할까 봐요."}, {"spk": "가", "t": "바빠서 오래 할 수 있을지 모르겠지만"}, {"spk": "나", "t": "우리 교회에서는 주말마다 깨끗한 환경을 위해 하천 청소 봉사를 실시하고 있는데 누구라도"}, {"spk": "가", "t": "외국인 근로자들에게 한국말을 가르치는 한글 교실에서 자원 봉사할 사람을 찾던데요."}, {"spk": "나", "t": "여기 있는 종합 검진을 모두 받으려면 비용이 꽤 비싼데, 어떻게 할 거야? -이라도 -을까 보다'를 사용해 보기와 같이 힘들어서 주말은 도우미에게 부탁하려고 한다."}, {"t": "", "br": 1}, {"spk": "가", "t": ")(쓰십시오)"}, {"spk": "나", "t": "어디에 어떻게 기부하는지 몰라서 ( )"}, {"spk": "가", "t": ")(쓰십시오)"}, {"spk": "나", "t": "노인 복지 지원( )"}, {"spk": "가", "t": ")(쓰십시오)"}, {"t": "", "br": 1}, {"spk": "리에", "t": "영수 씨, 월 그렇게 열심히 들여다보고 계세요?"}, {"spk": "영수", "t": "국외에 파견하는 봉사 인력 모집에 관한 안내문을 읽고 있던 참이었어요. 한국과 세계 여러 국가 간의 우호 협력 증진을 목적으로 설립된 단체에서 국외로 다양한 분야의 인력을 파견한다고 하네요."}, {"spk": "리에", "t": "영수 씨, 졸업하고 취직을 하는 줄 알았는데 외국에 나갈 계획이세요?"}, {"spk": "영수", "t": "네, 얼마 전에 방송된 다큐멘터리를 통해 국제 난민 구호 활동을 하는 젊은이들 이 많다는 걸 알게 됐거든요. 취직을 일이 년 미루더라도 젊었을 때 뭔가 뜻있는 일을 해야겠더라고요. 그래서 요즘 이것저것 알아보고 있어요. 국외로 나가면 견문도 넓힐 수 있을 것 같고요."}, {"spk": "리에", "t": "정말 좋은 생각이네요. 하긴 요즘은 세계가 점점 좁아져서 지구촌이란 말이 진짜 실감나요. 그런데 어느 나라에 가고 싶으세요?"}, {"spk": "영수", "t": "제가 도움이 될 수 있는 곳이라면 어디든지 상관없습니다. 봉사를 함으로써 남을 도울 수 있고 저도 배우면서 성장할 수 있을 것 같아요."}, {"spk": "영수", "t": "국제 봉사 인력 모집에 관한 안내문이에요."}, {"t": "", "br": 1}, {"t": "── 새 단어 ──", "h": 1}, {"t": "단체"}, {"t": "아동 보호 시설"}, {"t": "보육원"}, {"t": "입양 단체"}, {"t": "양로원"}, {"t": "장애인 시설"}, {"t": "쉼터"}, {"t": "무료 진료소"}, {"t": "재단"}, {"t": "대상"}, {"t": "저소득층 자녀"}, {"t": "결식아동"}, {"t": "소년 소녀 가장"}, {"t": "독거 노인"}, {"t": "영세민"}, {"t": "장애인"}, {"t": "노숙자"}, {"t": "이주 노동자"}, {"t": "결혼 이민 여성"}, {"t": "방법"}, {"t": "기부"}, {"t": "후원"}, {"t": "교육 봉사"}, {"t": "의료 봉사"}]}});
